using System.Diagnostics;using WAID.Application.Services;namespace WAID.Application.Tests;public sealed class DigitalTwinTests
{[Fact]public async Task Capture_is_versioned_hashed_compressed_and_redacted(){var repo=new Repo();var profile=Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);var service=new DigitalTwinService([new Provider("os",new Dictionary<string,string>{{"path",Path.Combine(profile,"data")},{"token","secret"}})],repo,TimeProvider.System);var x=await service.CaptureAsync(SystemSnapshotPurpose.Manual,false,null,null,CancellationToken.None);Assert.Equal(DigitalTwinService.SchemaVersion,x.SchemaVersion);Assert.Equal(64,x.IntegritySha256.Length);Assert.True(repo.Payload!.Length>0);Assert.DoesNotContain("token",x.Components[0].Values.Keys,StringComparer.OrdinalIgnoreCase);Assert.DoesNotContain(profile,x.Components[0].Values["path"],StringComparison.OrdinalIgnoreCase);service.Verify(x);}
 [Fact]public async Task Partial_component_failure_does_not_discard_successes(){var service=new DigitalTwinService([new Provider("good",new Dictionary<string,string>{{"state","ok"}}),new Provider("bad",fail:true)],new Repo(),TimeProvider.System);var x=await service.CaptureAsync(SystemSnapshotPurpose.Baseline,false,null,null,CancellationToken.None);Assert.Contains(x.Components,c=>c.Name=="good"&&c.State==SnapshotComponentState.Captured);Assert.Contains(x.Components,c=>c.Name=="bad"&&c.State==SnapshotComponentState.Failed);}
 [Fact]public async Task Diff_is_stable_and_labels_security_risk(){var repo=new Repo();var firstService=new DigitalTwinService([new Provider("security",new Dictionary<string,string>{{"defender","on"}})],repo,TimeProvider.System);var a=await firstService.CaptureAsync(SystemSnapshotPurpose.Manual,false,null,null,CancellationToken.None);var secondService=new DigitalTwinService([new Provider("security",new Dictionary<string,string>{{"defender","off"}})],repo,TimeProvider.System);var b=await secondService.CaptureAsync(SystemSnapshotPurpose.Manual,false,null,null,CancellationToken.None);var x=secondService.Compare(a,b);var y=secondService.Compare(a,b);Assert.Equal(x.Changes,y.Changes);Assert.Contains(x.RiskHighlights,h=>h.StartsWith("High",StringComparison.Ordinal));}
 [Fact]public async Task Integrity_and_compatibility_fail_closed(){var service=new DigitalTwinService([new Provider("os",new Dictionary<string,string>{{"v","1"}})],new Repo(),TimeProvider.System);var x=await service.CaptureAsync(SystemSnapshotPurpose.Manual,false,null,null,CancellationToken.None);Assert.Throws<DigitalTwinException>(()=>service.Verify(x with{SchemaVersion="future"}));Assert.Throws<DigitalTwinException>(()=>service.Verify(x with{Components=[x.Components[0]with{Values=new Dictionary<string,string>{{"v","tampered"}}}]}));}
 [Fact]public async Task Repair_pre_post_snapshots_require_and_preserve_links(){var repo=new Repo();var service=new DigitalTwinService([new Provider("os",new Dictionary<string,string>{{"v","1"}})],repo,TimeProvider.System);await Assert.ThrowsAsync<DigitalTwinException>(()=>service.CaptureAsync(SystemSnapshotPurpose.PreRepair,true,null,null,CancellationToken.None));var tx=Guid.NewGuid();var before=await service.CaptureAsync(SystemSnapshotPurpose.PreRepair,true,tx,null,CancellationToken.None);var after=await service.CaptureAsync(SystemSnapshotPurpose.PostRepair,true,tx,before.Id,CancellationToken.None);Assert.Equal(tx,after.RepairTransactionId);Assert.Equal(before.Id,after.RelatedSnapshotId);Assert.True(before.IsPinned&&after.IsPinned);}
 [Fact]public async Task Capture_performance_is_bounded_for_large_structured_component(){var values=Enumerable.Range(0,10_000).ToDictionary(i=>$"key{i:D5}",i=>$"value{i}");var service=new DigitalTwinService([new Provider("large",values)],new Repo(),TimeProvider.System);var sw=Stopwatch.StartNew();var x=await service.CaptureAsync(SystemSnapshotPurpose.Manual,false,null,null,CancellationToken.None);sw.Stop();Assert.Equal(10_000,x.Components[0].Values.Count);Assert.True(sw.Elapsed<TimeSpan.FromSeconds(5));}
 private sealed class Provider(string name,IReadOnlyDictionary<string,string>?values=null,bool fail=false):ISystemSnapshotComponentProvider{public string Name=>name;public string SerializerVersion=>"component-1.0";public Task<IReadOnlyDictionary<string,string>>CaptureAsync(CancellationToken t)=>fail?throw new InvalidOperationException("failure"):Task.FromResult(values??new Dictionary<string,string>());}private sealed class Repo:IDigitalTwinRepository{public readonly List<DigitalTwinSnapshot>Items=[];public byte[]?Payload;public Task SaveAsync(DigitalTwinSnapshot x,byte[]p,CancellationToken t){Items.Add(x);Payload=p;return Task.CompletedTask;}public Task<IReadOnlyList<DigitalTwinSnapshot>>GetRecentAsync(int c,CancellationToken t)=>Task.FromResult<IReadOnlyList<DigitalTwinSnapshot>>(Items);public Task<DigitalTwinSnapshot?>GetAsync(Guid id,CancellationToken t)=>Task.FromResult(Items.FirstOrDefault(x=>x.Id==id));public Task SaveDiffAsync(SystemSnapshotDiff d,CancellationToken t)=>Task.CompletedTask;public Task<SnapshotRetentionResult>ApplyRetentionAsync(DateTimeOffset r,CancellationToken t)=>Task.FromResult(new SnapshotRetentionResult(DateTimeOffset.UtcNow,1,0,0,"v"));}}
